function loadHeader(){if(!window.location.pathname.includes("newsletter-admin.html")){let t=document.createElement("div");t.id="header-container",document.body.insertBefore(t,document.body.firstChild),fetch("includes/header.html").then(e=>e.text()).then(e=>{t.innerHTML=e,initMobileMenu(),updateActiveLink()}).catch(e=>{console.error("Error al cargar el header:",e)})}}function initMobileMenu(){let t=document.querySelector(".hamburger"),n=document.querySelector(".nav-menu"),i=document.querySelector(".overlay");t&&n&&(t.addEventListener("click",function(){this.classList.toggle("active"),n.classList.toggle("active"),document.body.style.overflow=n.classList.contains("active")?"hidden":"",i&&(i.style.display=n.classList.contains("active")?"block":"none")}),document.querySelectorAll(".nav-menu a").forEach(e=>{e.addEventListener("click",()=>{t.classList.remove("active"),n.classList.remove("active"),document.body.style.overflow="",i&&(i.style.display="none")})}),i)&&i.addEventListener("click",()=>{t.classList.remove("active"),n.classList.remove("active"),i.style.display="none",document.body.style.overflow=""})}function updateActiveLink(){let n=window.location.pathname;document.querySelectorAll(".nav-menu > a").forEach(e=>{e.classList.remove("active");var t=e.getAttribute("href");t&&(n.endsWith(t)||"/periodico-digital/"===t&&(n.endsWith("index.html")||n.endsWith("/")))&&e.classList.add("active")})}document.addEventListener("DOMContentLoaded",loadHeader);